 dict(slug='yoga-lombok',title='Yoga in Lombok & the Gili Islands',category='Yoga',regions=None,intro='Compare yoga studios and yoga stays across Lombok and the Gili Islands. Choose an area first, then check whether the venue offers individual classes, private sessions or a stay-based programme.',notes=[('A class or a stay?','Ashtari, Mana, Rascals and Zora publish class information in Kuta. Xanadu focuses on surf-and-yoga stays; check the chosen property and programme before booking.'),('Choose your island','Gili Air and Gili Trawangan have several listed yoga spaces. Gili Meno has fewer options, so contact maoMeno before planning around a class.'),('Check this week’s schedule','Use the weekly agenda for published lesson times and the linked studio calendars for changes. Drop-in access is specific to the venue.')],faq=[('Where can I find a yoga class in Lombok?','Start with the studios listed in Kuta, or choose Gili Air or Gili Trawangan if you are staying on those islands. Open a profile to see its location and direct booking links.'),('Can I book a single class instead of a retreat?','Several studios publish individual classes. Retreat and accommodation listings can work differently; check the availability note on the profile before booking.')]),
 dict(slug='yoga-kuta-lombok',title='Yoga in Kuta Lombok',category='Yoga',regions=['Kuta Lombok'],intro='Find yoga in Kuta on Lombok’s south coast. Compare dedicated studios, yoga at accommodation venues and private sessions. This page concerns Kuta Lombok, not Kuta in Bali.',notes=[('Public studio classes','Ashtari, Mana, Rascals and Zora provide schedules or class-booking information. Use their own timetables to compare the session format and your travel dates.'),('Private sessions','Shanti arranges sessions by appointment and no longer has a fixed public studio schedule. Agree on the meeting point directly.'),('Stay-based yoga','Xanadu has two properties and programmes centred on stays. A listing here does not imply that an outside visitor can join a drop-in class.')],faq=[('Is this the Kuta in Bali?','No. These listings are in Kuta Lombok and the surrounding south-coast area in Indonesia.'),('Where can I compare yoga times in Kuta Lombok?','Open the agenda or the provider’s profile. Ashtari, Mana, Rascals and Zora link to their current class information.')]),
 dict(slug='yoga-gili-air',title='Yoga on Gili Air',category='Yoga',regions=['Gili Air'],intro='Explore yoga on Gili Air through three different settings: Flowers & Fire’s two studios, H2O’s yoga and meditation centre, and the more appointment-led approach at Slow.',notes=[('Two Flowers & Fire studios','The Yoga Garden and Seaside Yoga Studio are part of one provider. Use the separate map links on the profile to reach the correct studio.'),('A yoga and meditation base','H2O combines yoga and meditation with other wellness activities and accommodation. Ask the team about the sessions running during your stay.'),('A personal appointment','Slow describes personalised yoga or Pilates and spa treatments. Confirm a session with the team instead of assuming a public group timetable.')],faq=[('Which Flowers & Fire location should I go to?','Check the class listing first: Yoga Garden and Seaside Yoga Studio are different locations. Both map links are available on the provider profile.'),('Are all Gili Air classes drop-in?','Access varies. Check each provider’s timetable and booking instructions, especially for private sessions.')]),
