 dict(slug='sound-healing-lombok',title='Sound healing in Lombok & Gili Air',category='Sound healing',regions=None,intro='Find providers describing sound baths or sound sessions in Lombok and on Gili Air. Public workshops, private sessions and retreat activities have different booking arrangements; availability is shown on each profile.',notes=[('Group sessions and workshops','Ashtari and Flowers & Fire include sound in their published offerings. The agenda highlights dated or weekly sessions where a current time is available.'),('Private sound sessions','Shanti offers private sessions by arrangement. Agree on the format, place and group size directly with the provider.'),('Check availability first','Cocoon reports that on-site physical treatments are paused during restructuring. Contact the team before planning a visit for Reiki, sound or a retreat stay.')],faq=[('Are there sound sessions on Gili Air?','Flowers & Fire describes sound healing and workshops across its two studios. Check the linked schedule for the current programme and location.'),('Does a listing guarantee a session on my dates?','No. Open the profile and confirm the date and format with the provider; some sessions are private or part of a changing programme.')]),
 dict(slug='sound-healing-kuta-lombok',title='Sound healing in Kuta Lombok',category='Sound healing',regions=['Kuta Lombok'],intro='Compare sound-session options around Kuta Lombok: Ashtari’s published holistic offerings, Shanti’s private sessions and Cocoon’s enquiry-based availability. Start with the session format before choosing a place.',notes=[('A scheduled experience','Check Ashtari’s current event and booking information if you want a group sound session during your Kuta stay.'),('A private appointment','Shanti works with private spaces and selected venues. Contact the team to discuss the session and agree on a meeting point.'),('Availability needs checking','Cocoon’s on-site physical treatments are currently paused. Its profile explains the limitation; do not treat the listing as an open daily timetable.')],faq=[('Can I book private sound healing in Kuta Lombok?','Shanti describes private sound sessions by appointment. Ask about current availability, the session format and your preferred location.'),('Are all three listings open for walk-ins?','No. The profiles distinguish published schedules, appointments and availability that needs checking directly.')]),
 dict(slug='massage-lombok',title='Massage in Lombok & the Gili Islands',category='Massage',regions=None,intro='Compare massage and bodywork at day spas, resorts and wellness spaces. Location matters: the Kuta area, Senggigi, Selong Belanak and the Gili Islands have separate listings and access arrangements.',notes=[('Day-spa options in Kuta','My Spa and GLAZE publish massage and bodywork information. Use the treatment menu and contact links to choose an appointment.'),('A resort spa visit','Puri Mas welcomes outside spa guests by appointment, but its wellness location is separate from the beachfront resort. At Kuara, SENJA and Seri, ask about visitor access.'),('Massage on the islands','H2O and Slow list massage on Gili Air. Seri lists resort massage on Gili Meno. Confirm the treatment and place directly before going.')],faq=[('Can I visit a resort spa without staying there?','This depends on the venue. Puri Mas explicitly describes outside spa visitors by appointment. For other resorts, ask the team before travelling.'),('Does every yoga studio also offer massage?','No. This page includes only providers with massage in the reviewed listing. Cocoon’s paused physical treatments are excluded from the massage results.')]),
