PAGEMAP={p['slug']:p for p in PAGES}
def matches(f,p):return bool(set(p.get('categories',[p['category']])) & set(f['categories'])) and (not p['regions'] or f['region'] in p['regions'])
def begin(title,desc,path,image=None):
 s=I.head(title+' | Holistic Tribe Lombok',desc,path,image or '/assets/images/general/holistic-tribe-lombok-hero-refined.webp')
 return s.replace('</head>',f'<link rel="stylesheet" href="/assets/css/discovery.css?v={VERSION}" /></head>')+'<body class="discovery-page" data-page="profile">'+I.header()
def end():return I.footer()+I.end('profile')
def cards(fs):return '<div class="island-provider-grid">'+''.join(I.card(f) for f in fs)+'</div>'
def related_pages(f):return [p for p in PAGES if matches(f,p)]
def crumb(parts):return '<nav class="profile-breadcrumbs" aria-label="Breadcrumb"><a href="/">Home</a>'+''.join('<span>/</span>'+('<a href="'+url+'">'+E(label)+'</a>' if url else '<span>'+E(label)+'</span>') for label,url in parts)+'</nav>'
def photo_urls(f):
 return list(dict.fromkeys([x for x in [f.get('image','')]+f.get('gallery',[]) if x.startswith('/assets/') and (ROOT/x.lstrip('/')).is_file()]))
def sources(f):
 date=f.get('review',{}).get('checkedAt','2026-11-17');src=f.get('review',{}).get('sources',[])
 supplied='Profile information and photographs supplied by the provider. ' if f.get('contentSubmitted') else 'Based on the linked public sources. '
 return '<details class="profile-sources"><summary>Sources & updates <span aria-hidden="true">+</span></summary><p>'+E(supplied)+'Source information reviewed '+E(date)+'. Check current availability directly.</p><ul>'+''.join('<li><a href="'+E(u)+'" target="_blank" rel="noopener">'+E(u)+'</a></li>' for u in src)+'</ul><p>Are you the provider? <a href="mailto:hello@holistictribelombok.com">Send corrections or photographs</a>. Your profile and updates stay free.</p></details>'
def profile(f):
 links=f['links'];photos=photo_urls(f);url=links.get('booking') or links.get('whatsapp') or links.get('website') or links.get('instagram');label='Check classes & booking' if links.get('booking') else 'Contact the provider'
 heading=begin(f['name'],f['description'],f['url'],photos[0] if photos else None).replace('<body class="discovery-page"','<body class="discovery-page island-profile"')
 body='<main class="container refreshed-profile">'+crumb([('Providers','/facilitators/'),(f['region'],'/facilitators/?'+urlencode({'place':area(f)})),(f['name'],'')])
 body+='<div class="island-profile-title"><div><span class="small-label">'+E(f['region'])+'</span><h1>'+E(f['name'])+'</h1><p>'+E(f['profileLead'])+'</p></div><a class="island-button" href="'+E(url)+'" target="_blank" rel="noopener">'+label+' ↗</a></div>'
 if photos:
  body+='<section class="provider-photo-board '+('many' if len(photos)>1 else 'single')+'" aria-label="Photos of '+E(f['name'])+'">'
  for i,p in enumerate(photos[:4]):body+='<button class="profile-photo" type="button" data-photo="'+E(p)+'" data-caption="'+E(f['name']+' · photograph '+str(i+1))+'" aria-label="Open photograph '+str(i+1)+' of '+E(f['name'])+'"><img src="'+E(p)+'" alt="'+E(f['name'])+'" width="1200" height="800" '+('fetchpriority="high"' if i==0 else 'loading="lazy"')+' /></button>'
  body+='</section>'
 body+='<div class="island-profile-layout"><div class="island-profile-story"><section id="about"><span class="small-label">About the provider</span><h2>Meet '+E(f['name'])+'</h2><p>'+E(f['about'])+'</p><div class="profile-practice-tags">'+''.join('<span>'+E(t)+'</span>' for t in f['offerings'])+'</div></section>'
 if f.get('highlights'):
  body+='<section class="profile-experiences"><span class="small-label">What to expect</span><h2>Explore the offering.</h2>'+''.join('<div class="experience-row"><span class="experience-no">'+str(i+1).zfill(2)+'</span><div><h3>'+E(x['title'])+'</h3><p>'+E(x['text'])+'</p></div></div>' for i,x in enumerate(f['highlights']))+'</section>'
 if f.get('contentSubmitted') and f.get('reasons'):
  body+='<section class="profile-experiences"><h2>More about the place</h2>'+''.join('<h3>'+E(x['title'])+'</h3><p>'+E(x['text'])+'</p>' for x in f['reasons'])+'</section>'
 if len(photos)>4:
  body+='<section class="provider-gallery"><h2>More photographs</h2><div>'+''.join('<button class="profile-photo" type="button" data-photo="'+E(p)+'" data-caption="'+E(f['name']+' · photograph '+str(i+5))+'" aria-label="Open photograph '+str(i+5)+' of '+E(f['name'])+'"><img src="'+E(p)+'" alt="'+E(f['name'])+'" loading="lazy" width="800" height="600" /></button>' for i,p in enumerate(photos[4:]))+'</div></section>'
 body+=sources(f)+'</div><aside class="profile-visit-card" id="contact"><span class="small-label">Plan your visit</span><h2>Practical information</h2><dl><div><dt>Location</dt><dd>'+E(f['location'])+'</dd></div><div><dt>Activities</dt><dd>'+E(' · '.join(f['categories']))+'</dd></div></dl><div class="provider-availability"><strong>Before you go</strong><p>'+E(f['availabilityNote'])+'</p></div>'
 for key,title in [('booking','Schedule / booking'),('whatsapp','WhatsApp'),('website','Website'),('instagram','Instagram'),('facebook','Facebook'),('email','Email')]:
  u=links.get(key)
  if u:body+='<a class="'+('island-button' if key=='booking' or (not links.get('booking') and key=='whatsapp') else 'visit-secondary')+'" href="'+E(('mailto:' if key=='email' else '')+u)+'"'+(' target="_blank" rel="noopener"' if key!='email' else '')+'>'+title+' ↗</a>'
 locations=f.get('locations') or ([dict(name='Find the location',map=links['map'])] if links.get('map') else [])
 for loc in locations:body+='<a class="visit-map" href="'+E(loc['map'])+'" target="_blank" rel="noopener">'+E(loc['name'])+' · Google Maps ↗</a>'
 body+='<a class="visit-secondary" href="/agenda/?'+urlencode({'q':f['name']})+'">Find classes & events ↗</a></aside></div>'
 pages=related_pages(f)
 body+='<section class="discovery-crosslinks"><h2>Explore by practice & place</h2>'+''.join('<a href="/'+p['slug']+'/">'+E(p['title'])+' ↗</a>' for p in pages)+'</section>'
 scored=sorted([x for x in FS if x['id']!=f['id']],key=lambda x:(-(len(set(x['categories'])&set(f['categories']))*2+int(x['region']==f['region'])*3),not x.get('contentSubmitted',False),x['id']))[:3]
 body+='<section class="discovery-related"><div class="island-section-heading"><h2>Other providers to explore</h2><a href="/facilitators/">All providers ↗</a></div>'+cards(scored)+'</section></main>'
 if photos:body+='<dialog class="island-photo-dialog" data-photo-dialog aria-label="'+E(f['name'])+' photos"><button class="photo-dialog-close" type="button" data-photo-close aria-label="Close photos">×</button><button type="button" data-photo-prev aria-label="Previous photo">←</button><figure><img data-photo-large alt="" /><figcaption data-photo-caption></figcaption></figure><button type="button" data-photo-next aria-label="Next photo">→</button></dialog>'
 return heading+body+end()
def area(f):
 return {'Kuta Lombok':'kuta','Bumbang Beach, South Lombok':'kuta','Selong Belanak':'selong-belanak','Gili Air':'gili-air','Gili Trawangan':'gili-trawangan','Gili Meno':'gili-meno','Kerandangan / Senggigi':'senggigi'}.get(f['region'],'')
def discovery(p):
 found=[f for f in FS if matches(f,p)];body=begin(p['title'],p['intro'],'/'+p['slug']+'/')+'<main class="container discovery-main">'+crumb([('Explore practices','/explore/'),(p['title'],'')])
 body+='<section class="discovery-hero"><span class="small-label">Find a local provider</span><h1>'+E(p['title'])+'</h1><p>'+E(p['intro'])+'</p><div class="discovery-actions"><a class="island-button" href="#providers">Compare '+str(len(found))+' providers ↓</a><a class="island-text-link" href="/agenda/">Classes & events ↗</a></div></section>'
 body+='<section class="discovery-notes">'+''.join('<article><h2>'+E(title)+'</h2><p>'+E(text)+'</p></article>' for title,text in p['notes'])+'</section>'
 if p.get('comparison'):
  body=body.replace('</head>',question_styles()+'</head>')
  rows=[('Gili Air','Flowers & Fire, H2O, Slow','Check which studio or private-session location is listed.','/yoga-gili-air/'),('Gili Trawangan','Gili Yoga, Sunset Beach Yoga','Choose the class format, then check current times.','/yoga-gili-trawangan/'),('Gili Meno','maoMeno, Seri Resort','Confirm current yoga availability; Seri is listed for massage and retreat space.','/facilitators/?place=gili-meno')]
  body+='<section class="island-comparison"><h2>Compare the three islands</h2><div class="comparison-scroll"><table><caption>Listed yoga and wellness options, with practical booking differences</caption><thead><tr><th scope="col">Island</th><th scope="col">Listed providers</th><th scope="col">Before you book</th><th scope="col">Explore</th></tr></thead><tbody>'+''.join('<tr><th scope="row">'+E(name)+'</th><td>'+E(providers)+'</td><td>'+E(note)+'</td><td><a href="'+E(link)+'">View options ↗</a></td></tr>' for name,providers,note,link in rows)+'</tbody></table></div></section>'
 body+='<section class="discovery-results" id="providers"><div class="island-section-heading"><div><span class="small-label">'+str(len(found))+' listed providers</span><h2>Compare the options.</h2></div></div>'+cards(found)+'</section>'
 body+='<section class="discovery-faq"><h2>Planning your visit</h2>'+''.join('<details><summary>'+E(q)+'</summary><p>'+E(a)+'</p></details>' for q,a in p['faq'])+'</section>'
 body+='<section class="discovery-crosslinks"><h2>Related places & practices</h2>'+''.join('<a href="/'+x['slug']+'/">'+E(x['title'])+' ↗</a>' for x in PAGES if x['slug']!=p['slug'])+'</section>'
 body+='<details class="profile-sources"><summary>Sources & updates <span>+</span></summary><p>Provider source information reviewed on 17 November 2026. The comparison reflects the published provider profiles; schedules and visitor access can change.</p><ul>'+''.join('<li><a href="'+E(f['url'])+'">'+E(f['name'])+' · profile and sources</a></li>' for f in found)+'</ul></details></main>'+end()
 return body
def question_styles():
 return '<link rel="stylesheet" href="/assets/css/questions.css?v=20261117-questions-v1" />'
def question_routes():
 return '<section class="question-section" aria-labelledby="question-title"><h2 id="question-title">Start with your question.</h2><div class="discovery-notes">'+''.join('<article><h3>'+E(question)+'</h3><p>'+E(answer)+'</p><a href="/'+E(path)+('"' if '?' in path else '/"')+'>'+E(label)+' ↗</a></article>' for question,answer,path,label in QUESTIONS)+'</div></section>'
def hub():
 content=begin('Explore yoga, sound healing, massage & retreats in Lombok','Find a practice and a place in Lombok or the Gili Islands. Compare providers and connect directly.','/explore/')+'<main class="container discovery-main">'+crumb([('Explore practices','')])+'<section class="discovery-hero"><span class="small-label">Lombok & the Gili Islands</span><h1>Find a practice. Choose a place.</h1><p>Compare local providers, understand the options and connect directly. Start with a practice or an area below.</p></section>'+question_routes()+'<div class="discovery-hub-grid">'+''.join('<a href="/'+p['slug']+'/"><span class="small-label">'+str(sum(matches(f,p) for f in FS))+' providers</span><h2>'+E(p['title'])+'</h2><p>'+E(p['intro'])+'</p><span>Compare the options ↗</span></a>' for p in PAGES)+'</div><section class="discovery-crosslinks"><a href="/facilitators/">Browse all providers ↗</a><a href="/agenda/">Weekly classes & events ↗</a><a href="/holistic-practices/">Read the practice guides ↗</a></section></main>'+end()
 return content.replace('</head>',question_styles()+'</head>')

def main():
 for f in FS:
  if f['id'] in [6,13]:continue
  (ROOT/f['url'].lstrip('/')/'index.html').write_text(profile(f))
 for p in PAGES:
  target=ROOT/p['slug'];target.mkdir(exist_ok=True);(target/'index.html').write_text(discovery(p))
 target=ROOT/'explore';target.mkdir(exist_ok=True)
 (target/'index.html').write_text(hub())
 print('Rendered 21 profiles, 9 discovery pages and discovery hub. Kuara and Sunset retained.')
if __name__=='__main__':main()
